import sys

DEBUG = True


def main() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    if DEBUG:
        print(f"Debug: Input value is {n}")
    if n % 2 == 0:
        print("The number is even")
    else:
        print("The number is odd")


if __name__ == "__main__":
    main()
